<script setup lang="ts">
import {project} from '@project';import {defaultPlatform} from '../project';
const platform={...defaultPlatform,...project.platform};
import {computed,ref,watch,toRefs} from 'vue';import {commandCredentials} from '../state/access';import {useLiveCommand} from '../state/liveCommand';import {isStrip,isLed} from '../contracts';import RgbPanel from './RgbPanel.vue';import {ui,request,notify} from '../state/device';import {cborBody} from '../contracts/cbor';import {t} from '../state/appearance';import TrendChart from '../components/TrendChart.vue';import Icon from '../components/Icon.vue';import InfoButton from '../components/InfoButton.vue';
const kind=ref('pi'),duration=ref(5000),onMs=ref(200),period=ref(1000),core=ref(0),priority=ref(2),ledPeriod=ref(1000),duty=ref(50),enabled=ref(true),busy=ref(false);
const {user,password}=toRefs(commandCredentials);
function openAccess(){ui.page='access';history.replaceState(null,'','#access');}
const ledReady=ref(false);const experiment=computed(()=>ui.summary?.experiment),led=computed(()=>ui.summary?.led);watch(led,v=>{if(v&&!ledReady.value){ledPeriod.value=v.period_ms;duty.value=v.duty_pct;enabled.value=v.enabled;ledReady.value=true;}},{immediate:true});watch(()=>ui.info?.chip.cores,cores=>{if(cores&&core.value>=cores)core.value=0;});
async function send(path:string,data:Record<string,unknown>,live=false){if(!live)busy.value=true;try{const body=cborBody(data);const r=await request(path,{method:'POST',...body,headers:{...body.headers,Authorization:'Basic '+btoa(user.value+':'+password.value)}});if(!r.ok)throw Error(`${r.status}: ${r.text}`);if(ui.summary){if(path==='/api/v2/strip'&&isStrip(r.data))ui.summary.strip=r.data;if(path==='/api/v2/led'&&isLed(r.data))ui.summary.led=r.data;}if(!live)notify(t('Команда принята · CBOR','Command accepted · CBOR'),'success');}catch(e){if(live)throw e;notify(String(e),'error');}finally{if(!live)busy.value=false}}
const sendLive=(path:string,data:Record<string,unknown>)=>send(path,data,true);
const ledLive=useLiveCommand<Record<string,unknown>>(data=>sendLive('/api/v2/led',data));
watch([enabled,ledPeriod,duty],(next,previous)=>{if(ledReady.value&&led.value?.supported)ledLive.update({enabled:enabled.value,period_ms:Number(ledPeriod.value),duty_pct:Number(duty.value)},next[0]!==previous[0]);},{flush:'sync'});
const start=()=>send('/api/v2/experiments',{action:'start',kind:kind.value,duration_ms:Number(duration.value),on_ms:Number(onMs.value),period_ms:Number(period.value),core:Number(core.value),priority:Number(priority.value)});

</script>
<template><section class="panel"><div class="panel-head"><h2><Icon name="bolt"/>{{t('Нагрузка CPU','CPU workload')}}</h2><InfoButton :label="t('Эксперименты','Experiments')" :text="t('На эмуляторе нагрузки синтетические. Устройство выполняет реальную задачу, CPU измеряется SDK. Одновременно работает один эксперимент с явной остановкой. График 100 мс не является осциллограммой GPIO.','The emulator synthesizes CPU load. The device runs a real task with SDK measurements. One experiment runs at a time with explicit stop. A 100 ms chart is not a GPIO oscilloscope.')"/></div><div class="experiment-status"><span class="pill" :class="experiment?.running?'amber':''" data-testid="experiment-state">{{experiment?.running?t('Выполняется','Running'):t('Остановлен','Stopped')}}</span><span>{{experiment?.elapsed_ms??0}} / {{experiment?.duration_ms??5000}} ms</span><b>{{experiment?.progress_pct.toFixed(1)??0}}%</b><span>{{ui.info?.source==='device'?t('Измерения платы','Device measurements'):t('Модель','Synthetic model')}}</span></div><form class="experiment-form" @submit.prevent="start"><div class="effect-field"><span class="label">{{t('Режим','Mode')}}</span><div class="effect-buttons" role="group" :aria-label="t('Режим нагрузки','Workload mode')" data-testid="experiment-kind"><button type="button" data-testid="experiment-kind-pi" :aria-pressed="kind==='pi'" :class="{active:kind==='pi'}" @click="kind='pi'">π</button><button type="button" data-testid="experiment-kind-pulse" :aria-pressed="kind==='pulse'" :class="{active:kind==='pulse'}" @click="kind='pulse'"><Icon name="bolt"/>{{t('Импульсы CPU','CPU pulses')}}</button></div></div><label>{{t('Длительность, мс','Duration, ms')}}<input v-model.number="duration" type="number" min="1000" max="30000" step="1000"></label><label>{{t('Активная часть, мс','Active time, ms')}}<input v-model.number="onMs" type="number" min="1" :max="period" :disabled="kind!=='pulse'"></label><label>{{t('Период нагрузки, мс','Load period, ms')}}<input v-model.number="period" type="number" min="20" max="5000" :disabled="kind!=='pulse'"></label><label>{{t('Ядро','Core')}}<select v-model.number="core"><option v-for="n in ui.info?.chip.cores??1" :key="n" :value="n-1">{{n-1}}</option></select></label><label>{{t('Приоритет','Priority')}}<input v-model.number="priority" type="number" min="1" :max="platform.workloadPriorityMax"></label><div class="inline-actions"><button class="primary" :disabled="busy||experiment?.running||!ui.httpOnline"><Icon name="player-play"/>{{t('Запустить','Start')}}</button><button type="button" :disabled="busy||!experiment?.running||!ui.httpOnline" @click="send('/api/v2/experiments',{action:'stop'})"><Icon name="player-stop"/>{{t('Остановить','Stop')}}</button></div></form><div v-if="experiment?.kind==='pi'" class="pi-result"><span>π</span><strong class="mono" data-testid="pi-value">{{experiment?.iterations?experiment.pi.toFixed(10):'—'}}</strong><span class="muted">{{experiment?.iterations??0}} {{t('итераций','iterations')}}</span></div><TrendChart :points="ui.cpu" :window-ms="10000" :label="t('Нагрузка за 10 секунд, разрешение 100 мс','CPU over 10 seconds, 100 ms resolution')"/></section><section v-if="ui.info?.capabilities.led?.supported" class="panel"><div class="panel-head"><h2>{{t('Светодиод','LED')}} / {{platform.ledController?platform.ledController+' ':''}}GPIO{{led?.gpio}}</h2></div><div class="experiment-status" data-testid="led-state"><span :class="led?.level?'ok':''">{{led?.level?t('LED включён','LED on'):t('LED выключен','LED off')}}</span><span>{{t('Применено','Applied')}}: {{led?.period_ms??1000}} ms / {{led?.duty_pct??50}}%</span><span>{{led?.enabled?t('Генератор включён','Generator enabled'):t('Генератор выключен','Generator disabled')}}</span></div><div><div class="slider-row"><label for="led-period">{{t('Период','Period')}} <b>{{ledPeriod}} ms</b></label><input id="led-period" v-model.number="ledPeriod" type="range" min="20" max="5000" step="10"></div><div class="slider-row"><label for="led-duty">{{t('Доля включения','Duty cycle')}} <b>{{duty}}%</b></label><input id="led-duty" v-model.number="duty" type="range" min="0" max="100"></div><div class="inline-actions"><label class="checkbox"><input v-model="enabled" type="checkbox">{{t('Включить генератор','Enable generator')}}</label></div><div class="endpoint" role="status"><span v-if="ledLive.error.value" class="bad">{{ledLive.error.value}}</span><span v-else>{{ledLive.sending.value||ledLive.pending.value?t('Передача…','Sending…'):t('Живое управление','Live controls')}}</span></div></div></section><RgbPanel :send="sendLive"/><div class="command-access"><Icon name="lock"/><span>{{t('Управление от имени','Commands as')}} <b>{{user}}</b></span><button class="text-button" @click="openAccess">{{t('Учётные данные → Доступ','Credentials → Access')}}</button></div></template>
